/* Colorful CVN Z590M GAMING FROZEN V20 — direct HID control.
 * Endpoint: VID 2F4C / PID 1000, HID interface 02, usage page 0xFF01, usage 1.
 * Interface 01 is usage page 0xFF00 (firmware update) and is never touched.
 * Frame: 65-byte output reports, report id 0x00, magic 01 00 88,
 *        byte 4 = packet index (0..6) or 0xFF to commit, then 20 x R,G,B.
 *
 * Onboard LEDs sit on a polyline, confirmed one LED at a time on the board:
 *   wire slots  2..13  right edge, top -> bottom (slot 2 at the top)
 *   wire slots 14..15  lower right edge, continuing down
 *   wire slots 16..19  bottom edge, right -> left (slot 16 at the corner)
 */
export function Name() { return "Colorful CVN Z590M GAMING FROZEN V20"; }
export function VendorId() { return 0x2F4C; }
export function ProductId() { return 0x1000; }
export function Publisher() { return "Huy Nguyen"; }
export function Version() { return "1.0.0"; }
// Photo embedded as a data: URI: the plugin sandbox cannot address its own
// folder, and a file:// path would not survive being shipped. Regenerate with
// tools/embed_image_urls.py after changing the photo.
export function ImageUrl() {
	return "data:image/png;base64,";
}
export function Type() { return "HID"; }
export function DeviceType() { return "motherboard"; }
export function Size() { return [120, 120]; }
export function ConflictingProcesses() {
	return ["iGameCenter.exe", "iGameCenter.Service.exe", "iGame.LightingService.exe", "iGame.DynamikLight.exe"];
}

/* global
shutdownColor:readonly
LightingMode:readonly
forcedColor:readonly
*/

export function ControllableParameters() {
	return [
		{"property":"shutdownColor", "group":"lighting", "label":"Shutdown Color", description: "This color is applied to the device when the System, or SignalRGB is shutting down", "min":"0", "max":"360", "type":"color", "default":"#000000"},
		{"property":"LightingMode", "group":"lighting", "label":"Lighting Mode", description: "Determines where the device's RGB comes from. Canvas will pull from the active Effect, while Forced will override it to a specific color", "type":"combobox", "values":["Canvas", "Forced"], "default":"Canvas"},
		{"property":"forcedColor", "group":"lighting", "label":"Forced Color", description: "The color used when 'Forced' Lighting Mode is enabled", "min":"0", "max":"360", "type":"color", "default":"#009bde"},
	];
}

const PACKET_MAGIC = [0x00, 0x01, 0x00, 0x88];
const COMMIT_INDEX = 0xFF;
const LEDS_PER_PACKET = 20;
const PACKET_LEN = 65;
const TOTAL_LEDS = 140;       // controller buffer; iGame reports 140
const ONBOARD_LEDS = 18;
const ARGB_LEDS = 60;

let Endpoint = null;

export function Validate(endpoint) {
	const match = endpoint.usage_page === 0xFF01 && endpoint.usage === 1;
	if (match) { Endpoint = endpoint; }
	return match;
}

// Index 0 is the 12V header zone, 1..18 the onboard polyline, then the two 5V runs.
// Authored on a 120x120 canvas (SignalRGB shows it as 60x60 in the layout): every
// LED needs its own pixel, so the ARGB runs get a row each.
function buildLayout() {
	const names = ["12V RGB"];
	const positions = [[2, 2]];

	for (let i = 0; i < ONBOARD_LEDS; i++) {
		names.push(`Onboard ${i + 1}`);
		if (i < 14) {
			positions.push([116, 4 + i * 6]);            // right edge, top -> down
		} else {
			positions.push([116 - (i - 13) * 24, 116]);  // bottom edge, right -> left
		}
	}

	for (let header = 1; header <= 2; header++) {
		for (let i = 0; i < ARGB_LEDS; i++) {
			names.push(`ARGB ${header} - ${i + 1}`);
			positions.push([i * 2, 88 + header * 8]);
		}
	}

	return { names, positions };
}

const LAYOUT = buildLayout();

export function Initialize() {
	if (Endpoint) {
		device.set_endpoint(Endpoint.interface, Endpoint.usage, Endpoint.usage_page, Endpoint.collection);
	}
	const { names, positions } = LAYOUT;
	device.setName("Colorful CVN Z590M GAMING FROZEN V20");
	device.setSize([120, 120]);
	device.setControllableLeds(names, positions);
	device.log(`Colorful Z590M: ${names.length} LEDs, onboard polyline mapped`);
}

// Wire slot for each layout LED (the frame buffer is flat wire order).
function wireSlot(index) {
	if (index === 0) { return [0, 1]; }              // 12V zone drives both slots
	if (index <= ONBOARD_LEDS) { return [index + 1]; } // onboard 1..18 -> slots 2..19
	const argb = index - ONBOARD_LEDS - 1;
	return [20 + argb];                               // ARGB1 20..79, ARGB2 80..139
}

function sendFrame(colors) {
	const buf = new Array(TOTAL_LEDS * 3).fill(0);
	for (const [index, rgb] of colors.entries()) {
		for (const slot of wireSlot(index)) {
			buf[slot * 3] = rgb[0];
			buf[slot * 3 + 1] = rgb[1];
			buf[slot * 3 + 2] = rgb[2];
		}
	}

	for (let packet = 0; packet < TOTAL_LEDS / LEDS_PER_PACKET; packet++) {
		const out = [PACKET_MAGIC[0], PACKET_MAGIC[1], PACKET_MAGIC[2], PACKET_MAGIC[3], packet];
		for (let i = 0; i < LEDS_PER_PACKET * 3; i++) { out.push(buf[packet * LEDS_PER_PACKET * 3 + i]); }
		device.write(out, PACKET_LEN);
	}

	const commit = [PACKET_MAGIC[0], PACKET_MAGIC[1], PACKET_MAGIC[2], PACKET_MAGIC[3], COMMIT_INDEX];
	for (let i = 0; i < LEDS_PER_PACKET * 3; i++) { commit.push(0x00); }
	device.write(commit, PACKET_LEN);
}

function hexToRgb(hex) {
	const value = parseInt(hex.replace("#", ""), 16);
	return [(value >> 16) & 0xFF, (value >> 8) & 0xFF, value & 0xFF];
}

export function Render() {
	const override = LightingMode === "Forced" ? hexToRgb(forcedColor) : null;
	sendFrame(LAYOUT.positions.map(([x, y]) => override || device.color(x, y)));
}

export function Shutdown(SystemSuspending) {
	const color = hexToRgb(SystemSuspending ? "#000000" : shutdownColor);
	sendFrame(new Array(LAYOUT.positions.length).fill(color));
}
